W,H=landscape(A3);c=canvas.Canvas(str(O/'DOSSIER_G3_JUSTIFICACION_LUZ_Y_PLANTA_BAJA.pdf'),pagesize=(W,H));c.setTitle('G3 · Justificación, luz y planta baja · V5');style=ParagraphStyle('p',fontName='Helvetica',fontSize=13,leading=19,textColor=HexColor('#25382f'));small=ParagraphStyle('s',parent=style,fontSize=10,leading=14)
